		t.Fatalf("schedule %s->%s: %v", acct, plan, err)
	}
	return r
}

func TestSchedulePlanChangeSnapshotAndIdempotency(t *testing.T) {
	s, clk := newTestService(utc(2026, 1, 15, 12, 0))
